fn recorder(fired: &Arc<Mutex<Vec<String>>>, name: &'static str) -> MfeHandler {
    let fired = fired.clone();
    handler(move |_context| {
        let fired = fired.clone();
        async move {
            fired.lock().unwrap().push(name.to_string());
            Ok(())
        }
    })
}

/// The manifest's hooks actually FIRE — the Swift lane shipped a hook engine
/// wired to nothing once, green under every text assertion (ADR-098).
#[test]
fn manifest_hooks_fire() {
    let fired = Arc::new(Mutex::new(Vec::new()));
    let mut deps = MfeDependencies::default();
    deps.custom_handlers.insert("onLoadBegin".to_string(), recorder(&fired, "onLoadBegin"));
    deps.custom_handlers.insert("onLoadComplete".to_string(), recorder(&fired, "onLoadComplete"));
    deps.custom_handlers.insert("onLoadError".to_string(), recorder(&fired, "onLoadError"));
    deps.custom_handlers.insert("onRenderBegin".to_string(), recorder(&fired, "onRenderBegin"));
    deps.custom_handlers.insert("onRenderComplete".to_string(), recorder(&fired, "onRenderComplete"));
    deps.custom_handlers.insert("onRenderError".to_string(), recorder(&fired, "onRenderError"));
    let mfe = mfe_with(deps);
    block_on(mfe.load(MfeContext::new())).expect("load");

    let ran = fired.lock().unwrap().clone();
    assert!(!ran.is_empty(), "no manifest hook fired during load()");
    assert!(ran.contains(&"onLoadBegin".to_string()), "before hook onLoadBegin did not fire");
    assert!(ran.contains(&"onLoadComplete".to_string()), "after hook onLoadComplete did not fire");
}

/// A host's handler wins over the generated stub for the same name.
#[test]
fn host_handler_overrides_generated_stub() {
    let fired = Arc::new(Mutex::new(Vec::new()));
    let mut deps = MfeDependencies::default();
    deps.custom_handlers.insert("onLoadBegin".to_string(), recorder(&fired, "host"));
    let mfe = mfe_with(deps);
    block_on(mfe.load(MfeContext::new())).expect("load");
    assert!(fired.lock().unwrap().contains(&"host".to_string()), "host handler was shadowed by the generated stub");
}

// ---- query transport
//
// `do_query` and `BffClient` share one HTTP path (`GraphQlPost::send`) and
// keep DIFFERENT error policies on purpose. These run the real code over a
// stub transport, so the split is asserted rather than incidental.

#[test]
fn query_returns_partial_data_and_errors_together() {
    let transport = StubTransport::new(200, PARTIAL);
    let mfe = mfe_with(MfeDependencies { transport: Some(transport), ..MfeDependencies::default() });
    block_on(mfe.load(MfeContext::new())).expect("load");
    let result = block_on(mfe.query(query_context())).expect("query");
    // The envelope policy: the capability answers with both halves.
    assert_eq!(result.data, Some(serde_json::json!({ "x": 1 })));
    assert_eq!(result.errors.iter().map(|e| e.message.as_str()).collect::<Vec<_>>(), vec!["boom"]);
}

#[test]
fn query_returns_errors_rather_than_failing_on_http_failure() {
    let transport = StubTransport::new(503, "nope");
    let mfe = mfe_with(MfeDependencies { transport: Some(transport), ..MfeDependencies::default() });
    block_on(mfe.load(MfeContext::new())).expect("load");
    let result = block_on(mfe.query(query_context())).expect("query");
    assert_eq!(result.data, None);
    assert_eq!(result.errors.len(), 1);
}

