#[test]
fn query_forwards_the_bearer_token_and_headers() {
    let transport = StubTransport::new(200, r#"{"data":{}}"#);
    let mfe = mfe_with(MfeDependencies { transport: Some(transport.clone()), ..MfeDependencies::default() });
    block_on(mfe.load(MfeContext::new())).expect("load");
    block_on(mfe.query(query_context().with_jwt("tok").with_header("X-Request-Id", "abc"))).expect("query");

    let seen = transport.seen.lock().unwrap().clone().expect("transport was not called");
    assert_eq!(seen.url, "http://stub.invalid/graphql");
    assert_eq!(seen.headers.get("Authorization").map(String::as_str), Some("Bearer tok"));
    assert_eq!(seen.headers.get("X-Request-Id").map(String::as_str), Some("abc"));
    assert_eq!(seen.headers.get("Content-Type").map(String::as_str), Some("application/json"));
}

#[test]
fn bff_client_fails_on_the_same_partial_response() {
    // Same bytes, opposite policy: a caller decoding into a type must not
    // silently receive half a response.
    let client = BffClient::new("http://stub.invalid/graphql", StubTransport::new(200, PARTIAL));
    let result: Result<serde_json::Value, MfeError> = block_on(client.query("query { x }", None));
    assert!(matches!(result, Err(MfeError::GraphQl { .. })));
}

#[test]
fn the_generated_provider_sends_the_capability_document() {
    let transport = StubTransport::new(200, r#"{"data":{}}"#);
    let mfe = MeridianCrewServicesMfe::with_transport(transport.clone(), MfeDependencies::default());
    block_on(mfe.provider().crew_roster()).expect("provider");
    let seen = transport.seen.lock().unwrap().clone().expect("transport was not called");
    let body: serde_json::Value = serde_json::from_slice(&seen.body).unwrap();
    assert_eq!(body["query"], meridian_crew_services::features::crew_roster_query::DOCUMENT);
}

#[test]
fn transition_table_matches_contract() {
    // The six states and their edges come from the platform contract.
    assert_eq!(MfeLifecycleState::ALL.len(), 6);
    assert!(MfeLifecycleState::Uninitialized.can_transition_to(MfeLifecycleState::Loading));
    assert!(!MfeLifecycleState::Destroyed.can_transition_to(MfeLifecycleState::Loading));
}

